#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<string> grid(N);
    for (int i = 0; i < N; ++i) {
        cin >> grid[i];
    }

    vector<string> next(N, string(N, '0'));

    for (int step = 0; step < Q; ++step) {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                int live = 0;

                for (int di = -1; di <= 1; ++di) {
                    for (int dj = -1; dj <= 1; ++dj) {
                        if (di == 0 && dj == 0) continue;

                        int ni = i + di;
                        int nj = j + dj;

                        if (ni >= 0 && ni < N && nj >= 0 && nj < N && grid[ni][nj] == '1') {
                            ++live;
                        }
                    }
                }

                if (grid[i][j] == '1') {
                    next[i][j] = (live == 2 || live == 3) ? '1' : '0';
                } else {
                    next[i][j] = (live == 3) ? '1' : '0';
                }
            }
        }

        grid.swap(next);
        for (int i = 0; i < N; ++i) {
            fill(next[i].begin(), next[i].end(), '0');
        }
    }

    for (int i = 0; i < N; ++i) {
        cout << grid[i] << '\n';
    }

    return 0;
}
